-- Phase 10b task 1: languages are data. Generated by drizzle-kit, then
-- rewritten by hand (see "Why the backups" below).
--
-- 1. `language`, seeded with nl (the default), en and fr.
-- 2. `user.locale` and `sponsor.locale` lose their hard-coded CHECK
--    (`IN ('nl', 'en', 'fr')`) and reference `language(code)` instead. SQLite
--    cannot alter a CHECK or add a foreign key to an existing column, so both
--    tables are rebuilt (create new, copy, drop, rename, recreate indexes and
--    the trigger).
--
-- Why the backups. D1 applies a migration inside a transaction, where
-- `PRAGMA foreign_keys = OFF` is a no-op (the toggles drizzle-kit generates
-- are left out). With foreign keys on, `DROP TABLE` performs an implicit
-- `DELETE FROM`, which RUNS the foreign key actions: dropping `user` would
-- cascade-delete every session, account, passkey, favorite and list, null
-- `audit_log.actor_id`, and dropping `sponsor` would fail on the RESTRICT
-- from `sponsorship` (or, without it, delete every `invoice_request`). So
-- each rebuild first copies every dependent row (and the SET NULL columns)
-- into a `_bk_*` table, removes what the drop would otherwise cascade or
-- restrict, rebuilds, copies the rows back in foreign key order and drops
-- the backups. `test/migration-0015.test.ts` runs it on seeded data and
-- compares every table before and after.
--
-- The rebuild of `user` also drops the trigger `user_keep_one_admin` (0007),
-- so it is created again here, byte for byte as in 0007 (a test applies the
-- last-admin scenarios after this migration).
CREATE TABLE `language` (
	`code` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`intl_tag` text NOT NULL,
	`enabled` integer DEFAULT true NOT NULL,
	`is_default` integer DEFAULT false NOT NULL,
	`sort_order` integer DEFAULT 0 NOT NULL,
	CONSTRAINT "language_code_length_check" CHECK(length("code") BETWEEN 2 AND 35),
	CONSTRAINT "language_name_length_check" CHECK(length("name") BETWEEN 1 AND 80),
	CONSTRAINT "language_intl_tag_length_check" CHECK(length("intl_tag") BETWEEN 2 AND 35),
	CONSTRAINT "language_default_enabled_check" CHECK(NOT ("is_default" = 1 AND "enabled" = 0))
);
--> statement-breakpoint
CREATE UNIQUE INDEX `language_default_uq` ON `language` (`is_default`) WHERE "is_default" = 1;--> statement-breakpoint
CREATE INDEX `language_menu_idx` ON `language` (`enabled`,`sort_order`,`code`);--> statement-breakpoint
INSERT INTO `language` (`code`, `name`, `intl_tag`, `enabled`, `is_default`, `sort_order`) VALUES ('nl', 'Nederlands', 'nl-BE', 1, 1, 0), ('en', 'English', 'en-BE', 1, 0, 1), ('fr', 'Français', 'fr-BE', 1, 0, 2);--> statement-breakpoint
CREATE TRIGGER `language_keep_default`
BEFORE DELETE ON `language`
WHEN OLD.`is_default` = 1
BEGIN
	SELECT RAISE(ABORT, 'default_language');
END;--> statement-breakpoint
