UPDATE `audit_log` SET `actor_id` = (SELECT `actor_id` FROM `_bk_audit_actor` WHERE `_bk_audit_actor`.`id` = `audit_log`.`id`) WHERE `id` IN (SELECT `id` FROM `_bk_audit_actor`);--> statement-breakpoint
UPDATE `sponsorship_event` SET `actor_id` = (SELECT `actor_id` FROM `_bk_event_actor` WHERE `_bk_event_actor`.`id` = `sponsorship_event`.`id`) WHERE `id` IN (SELECT `id` FROM `_bk_event_actor`);--> statement-breakpoint
CREATE TRIGGER `user_keep_one_admin`
BEFORE UPDATE OF `role` ON `user`
WHEN OLD.`role` = 'admin' AND NEW.`role` <> 'admin' AND NOT EXISTS (
	SELECT 1 FROM `user` AS `other`
	WHERE `other`.`role` = 'admin'
		AND `other`.`id` <> OLD.`id`
		AND NOT (
			coalesce(`other`.`banned`, 0) = 1
			AND (
				`other`.`ban_expires` IS NULL
				OR `other`.`ban_expires` > CAST(unixepoch('subsec') * 1000 AS INTEGER)
			)
		)
)
BEGIN
	SELECT RAISE(ABORT, 'last_admin');
END;--> statement-breakpoint
